begin
  if (select count(*) from public.teams where kind = 'competition_team' and layer_key = 'senior' and age_band = 'senior' and status = 'active') <> 1 then
    raise exception 'expected exactly one active senior first team (台中FUTURO 一線隊)';
  end if;
  if not exists (select 1 from public.seasons where label = '2026/27') then
    raise exception 'season 2026/27 missing (migration 20261009110000_site_public_api_v1.sql)';
  end if;
  if not exists (select 1 from public.competitions where slug = 'tfpl') then
    raise exception 'competition tfpl missing (migration 20261009110000_site_public_api_v1.sql)';
  end if;
end
$$;

