do $$
declare
  v_team uuid := (select id from public.teams where kind = 'competition_team' and layer_key = 'senior' and age_band = 'senior' and status = 'active');
  v_season uuid := (select id from public.seasons where label = '2026/27');
  v_competition uuid := (select id from public.competitions where slug = 'tfpl');
  f record;
  v_session uuid;
  v_club uuid;
  v_venue uuid;
  v_created integer := 0;
  v_filled integer := 0;
begin
  for f in select * from futuro_fixture_import order by round_no loop
    v_club := (select id from public.clubs where slug = f.opponent_club_slug);
    v_venue := (select id from public.public_venues where slug = f.venue_slug);

    -- Same round of this season and competition, else same kickoff, for the first team.
    select s.id into v_session
    from public.training_sessions s
    join public.match_publications p on p.session_id = s.id
    where s.team_id = v_team
      and s.deleted_at is null
      and public.is_match_session_kind(s.kind)
      and (
        (p.season_id = v_season and p.competition_id = v_competition and p.round_no = f.round_no)
        or s.starts_at = f.starts_at
      )
    order by (p.round_no is not distinct from f.round_no) desc, s.created_at
    limit 1;

    if v_session is null then
      insert into public.training_sessions (team_id, title, kind, starts_at, ends_at, location)
      values (v_team, f.title, 'league', f.starts_at, f.ends_at, f.location)
      returning id into v_session;

      insert into public.match_publications (
        session_id, opponent, opponent_club_id, side, is_published, public_status,
        club_score, opponent_score, result_entered_at,
        public_venue_id, season_id, competition_id, round_no,
        replay_url, replay_video_id, video_title
      ) values (
        v_session, f.opponent, v_club, f.side, false, f.status,
        f.club_score, f.opponent_score, case when f.status = 'completed' then f.ends_at end,
        v_venue, v_season, v_competition, f.round_no,
        f.replay_url, f.replay_video_id, f.video_title
      );
      v_created := v_created + 1;
    else
      -- Existing match: only fill what is still empty; never overwrite admin edits.
      update public.match_publications p set
        opponent = coalesce(p.opponent, f.opponent),
        opponent_club_id = coalesce(p.opponent_club_id, v_club),
        public_venue_id = coalesce(p.public_venue_id, v_venue),
        season_id = coalesce(p.season_id, v_season),
        competition_id = coalesce(p.competition_id, v_competition),
        round_no = coalesce(p.round_no, f.round_no)
      where p.session_id = v_session
        and (
          (p.opponent is null and f.opponent is not null)
          or (p.opponent_club_id is null and v_club is not null)
          or (p.public_venue_id is null and v_venue is not null)
          or p.season_id is null or p.competition_id is null or p.round_no is null
        );
      if found then v_filled := v_filled + 1; end if;

      update public.match_publications p set
        public_status = 'completed',
        club_score = f.club_score,
        opponent_score = f.opponent_score,
        result_entered_at = f.ends_at
      where p.session_id = v_session
        and f.status = 'completed'
        and p.public_status = 'scheduled'
        and p.club_score is null;
      if found then v_filled := v_filled + 1; end if;

      update public.match_publications p set
        replay_url = f.replay_url,
        replay_video_id = f.replay_video_id,
        video_title = coalesce(p.video_title, f.video_title)
      where p.session_id = v_session
        and f.replay_video_id is not null
        and p.replay_video_id is null
        and p.replay_url is null;
      if found then v_filled := v_filled + 1; end if;
    end if;
  end loop;
  raise notice 'futuro fixtures: % created, % filled in', v_created, v_filled;
end
$$;

-- Standings (16) ------------------------------------------------------------------
insert into public.standings (season_id, competition_id, after_round, club_id, rank, played, won, drawn, lost, goals_for, goals_against, points, is_official, source_url, fetched_at)
select se.id, co.id, v.after_round, cl.id, v.rank, v.played, v.won, v.drawn, v.lost, v.goals_for, v.goals_against, v.points, v.is_official, v.source_url, v.fetched_at::timestamptz
from (values
  ('kaohsiung-attackers', 1, 1, 1, 1, 0, 0, 5, 2, 3, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('taipower', 1, 2, 1, 1, 0, 0, 1, 0, 3, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('tatung', 1, 2, 1, 1, 0, 0, 1, 0, 3, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('hang-yuan', 1, 4, 1, 0, 1, 0, 1, 1, 1, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('tainan-tsg', 1, 4, 1, 0, 1, 0, 1, 1, 1, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('ac-taipei', 1, 6, 1, 0, 0, 1, 0, 1, 0, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('taichung-futuro', 1, 6, 1, 0, 0, 1, 0, 1, 0, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('taichung-rock', 1, 8, 1, 0, 0, 1, 2, 5, 0, false, 'https://www.ctfa.com.tw/2026-a', '2026-10-03T00:00:00+08:00'),
  ('kaohsiung-attackers', 2, 1, 2, 2, 0, 0, 7, 2, 6, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00'),
  ('taipower', 2, 2, 2, 2, 0, 0, 4, 1, 6, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00'),
  ('tatung', 2, 3, 2, 1, 1, 0, 1, 0, 4, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00'),
  ('ac-taipei', 2, 4, 2, 1, 0, 1, 2, 1, 3, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00'),
  ('hang-yuan', 2, 5, 2, 0, 2, 0, 1, 1, 2, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00'),
  ('tainan-tsg', 2, 6, 2, 0, 1, 1, 1, 3, 1, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00'),
  ('taichung-futuro', 2, 7, 2, 0, 0, 2, 0, 3, 0, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00'),
  ('taichung-rock', 2, 8, 2, 0, 0, 2, 3, 8, 0, true, 'https://www.ctfa.com.tw/2026-a/ranking/67-tfpl2026/0.html', '2026-10-03T00:00:00+08:00')
) as v(club_slug, after_round, rank, played, won, drawn, lost, goals_for, goals_against, points, is_official, source_url, fetched_at)
join public.clubs cl on cl.slug = v.club_slug
cross join (select id from public.seasons where label = '2026/27') se
cross join (select id from public.competitions where slug = 'tfpl') co
on conflict (season_id, competition_id, after_round, club_id) do update set
  rank = excluded.rank,
  played = excluded.played,
  won = excluded.won,
  drawn = excluded.drawn,
  lost = excluded.lost,
  goals_for = excluded.goals_for,
  goals_against = excluded.goals_against,
  points = excluded.points,
  is_official = excluded.is_official,
  source_url = excluded.source_url,
  fetched_at = excluded.fetched_at
where (standings.rank, standings.played, standings.won, standings.drawn, standings.lost, standings.goals_for, standings.goals_against, standings.points, standings.is_official, standings.source_url, standings.fetched_at)
  is distinct from (excluded.rank, excluded.played, excluded.won, excluded.drawn, excluded.lost, excluded.goals_for, excluded.goals_against, excluded.points, excluded.is_official, excluded.source_url, excluded.fetched_at);

commit;
